#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    // Returns an integer rank according to
    // Bool < Int8 < Int16 < Int32 < Int64 < Float32 < Float64 < Complex64 < Complex128
    fn rank(&self) -> u8 {
        match self {
            NumpyDType::Bool       => 0,
            NumpyDType::Int8       => 1,
            NumpyDType::Int16      => 2,
            NumpyDType::Int32      => 3,
            NumpyDType::Int64      => 4,
            NumpyDType::Float32    => 5,
            NumpyDType::Float64    => 6,
            NumpyDType::Complex64  => 7,
            NumpyDType::Complex128 => 8,
        }
    }
}

pub enum NumpyOperand {
    Scalar(NumpyDType),
    Array(NumpyDType),
}

impl NumpyOperand {
    // Extract the annotated data type
    fn dtype(&self) -> NumpyDType {
        match *self {
            NumpyOperand::Scalar(dt) => dt,
            NumpyOperand::Array(dt)  => dt,
        }
    }
}

/// Given a non-empty Vec of operands, returns the promotion
/// dtype which is the maximum‐ranked dtype present.
pub fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    // Safe to unwrap because the problem guarantees non-empty input
    let mut best = operands[0].dtype();
    for op in &operands[1..] {
        let dt = op.dtype();
        if dt.rank() > best.rank() {
            best = dt;
        }
    }
    best
}

fn main() {
    // A few quick smoke tests:
    let v1 = vec![
        NumpyOperand::Scalar(NumpyDType::Bool),
        NumpyOperand::Array(NumpyDType::Int16),
        NumpyOperand::Scalar(NumpyDType::Float32),
    ];
    assert_eq!(result_type(v1), NumpyDType::Float32);

    let v2 = vec![
        NumpyOperand::Array(NumpyDType::Complex64),
        NumpyOperand::Scalar(NumpyDType::Complex128),
        NumpyOperand::Scalar(NumpyDType::Int8),
    ];
    assert_eq!(result_type(v2), NumpyDType::Complex128);

    println!("All tests passed!");
}